import{_ as a,c as r,o as t,ag as s}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Create-user","description":"","frontmatter":{"title":"Create-user"},"headers":[],"relativePath":"general/create-user.md","filePath":"general/create-user.md","lastUpdated":null}'),o={name:"general/create-user.md"};function i(n,e,c,l,h,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="create-user" tabindex="-1">Create-user <a class="header-anchor" href="#create-user" aria-label="Permalink to &quot;Create-user&quot;">​</a></h1><h2 id="create-sso-user" tabindex="-1">Create SSO User <a class="header-anchor" href="#create-sso-user" aria-label="Permalink to &quot;Create SSO User&quot;">​</a></h2><p>Select Admin have access to administer the IrregularChat Login. This gives a lot of control which could be misused or could accidentally mess up users’ experience. Keep that in mind as you perform any admin action on <a href="https://sso.irregularchat.com" target="_blank" rel="noreferrer">https://sso.irregularchat.com</a></p><p>Return to <a href="/general/admin.html">Admin Links</a></p><h3 id="command-line-version" tabindex="-1">Command Line Version <a class="header-anchor" href="#command-line-version" aria-label="Permalink to &quot;Command Line Version&quot;">​</a></h3><p>Follow the steps from the github repo: <a href="https://github.com/irregularchat/authentik-account-creation" target="_blank" rel="noreferrer">https://github.com/irregularchat/authentik-account-creation</a></p><p>This uses your admin API with a python script which will create a user, set passwords, create invite links and configure it with a basic community message to send to a user.</p><h3 id="steps-to-create-a-user" tabindex="-1">Steps to Create a User <a class="header-anchor" href="#steps-to-create-a-user" aria-label="Permalink to &quot;Steps to Create a User&quot;">​</a></h3><p>See the official authentik guide: <a href="https://docs.goauthentik.io/docs/user-group-role/user/user_basic_operations#create-a-user" target="_blank" rel="noreferrer">https://docs.goauthentik.io/docs/user-group-role/user/user_basic_operations#create-a-user</a></p><p>In the Admin interface of your authentik instance, select Directory &gt; Users in the left side menu. Select the folder where you want to create a user. <code>Root &amp;gt; Users</code> - Direct link: <a href="https://sso.irregularchat.com/if/admin/#/identity/users" target="_blank" rel="noreferrer">https://sso.irregularchat.com/if/admin/#/identity/users</a> Click Create (Blue Button near the Search option) Fill in : 1. Username: This value must be unique and should be a persons first name and last initial (First-L) or signal username. 1. Name: Displayed whatever the user has introduced themselves by first name 1. User Type: LEAVE THIS as INTERNAL 1. add in a known email if available OR users’ username and @irregularchat.com 1. Active: LEAVE THIS as Active 1. Path: LEAVE THIS as users 1. Attributes: LEAVE THIS as {} Click Create</p><p>Next Step is REQUIRED:</p><h3 id="set-or-reset-user-password" tabindex="-1">Set OR Reset User Password <a class="header-anchor" href="#set-or-reset-user-password" aria-label="Permalink to &quot;Set OR Reset User Password&quot;">​</a></h3><p>This step is also how you reset the password for a user.</p><p>The BEST option is to <code>Create Recovery Link</code></p><p>In the Admin interface of your authentik instance, select Directory &gt; Users in the left side menu. Select the folder where you want to create a user. <code>Root &amp;gt; Users</code></p><h2 id="search-for-user" tabindex="-1">Search for user <a class="header-anchor" href="#search-for-user" aria-label="Permalink to &quot;Search for user&quot;">​</a></h2><h2 id="select-user" tabindex="-1">Select user <a class="header-anchor" href="#select-user" aria-label="Permalink to &quot;Select user&quot;">​</a></h2><h2 id="scroll-down-and-select-set-password-on-the-left-navigation-column" tabindex="-1">Scroll down and select <code>Set Password</code> on the left navigation column <a class="header-anchor" href="#scroll-down-and-select-set-password-on-the-left-navigation-column" aria-label="Permalink to &quot;Scroll down and select `Set Password` on the left navigation column&quot;">​</a></h2><ol><li><p>(BEST OPTION) Create Recovery Link</p></li><li><p>(Alt Option) Set Password #* This can be done with a passphrase generator such as <a href="https://bitwarden.com/password-generator/" target="_blank" rel="noreferrer">https://bitwarden.com/password-generator/</a> #* Select <code>Update Password</code></p></li></ol>',19)])])}const m=a(o,[["render",i]]);export{p as __pageData,m as default};
